  },
  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "url": {
      "type": "string",
      "description": "The absolute http(s) URL to fetch"
    }
  },
  "required": [
    "url"
  ]
}

{
  "type": "object",
  "properties": {
    "op": {
      "type": "string",
      "enum": [
        "check",
        "path",
        "get",
